function solve(input) {
  const cache = new Map();
  const results = [];

  for (const op of input) {
    if (op.op === 'put') {
      cache.set(op.key, { value: op.value, expiration: op.t + op.ttl });
    } else if (op.op === 'get') {
      const entry = cache.get(op.key);
      if (entry) {
        if (op.t < entry.expiration) {
          results.push(entry.value);
        } else {
          results.push(null);
        }
      } else {
        results.push(null);
      }
    } else if (op.op === 'delete') {
      cache.delete(op.key);
    }
  }

  return results;
}

